#!/usr/bin/env Rscript

options(stringsAsFactors = FALSE, warn = 1)

## ============================================================================
## 09_audit_marker_pseudobulk_support.R
##
## PURPOSE
## -------
## Audit biological/statistical support of the pseudobulks generated by:
##
##   08_build_candidate_marker_pseudobulk.R
##
## IMPORTANT
## ---------
## - No expression matrices are loaded.
## - No pseudobulk is removed.
## - No marker DE is performed.
## - No final minimum-cell threshold is selected.
##
## Sensitivity grid:
##
##   >=1, >=5, >=10, >=20, >=50 cells / pseudobulk
##
## The purpose is to determine how sample/donor/site support changes across
## these thresholds before choosing the formal marker-DE inclusion rule.
## ============================================================================


## ============================================================================
## 0. Configuration
## ============================================================================

PROJECT_ROOT <- "/home/mazekai/IBD_EcoTyper"

INPUT_ROOT <- file.path(
  PROJECT_ROOT,
  "03_reference/combined_reference/output/08_marker_pseudobulk"
)

OUTDIR <- file.path(
  PROJECT_ROOT,
  "03_reference/combined_reference/output/09_marker_pseudobulk_support_audit"
)

SUPPORT_THRESHOLDS <- c(
  1L,
  5L,
  10L,
  20L,
  50L
)

OVERWRITE <- identical(
  Sys.getenv("IBD_SUPPORT_AUDIT_OVERWRITE"),
  "1"
)

SUMMARY_FILE <- file.path(
  INPUT_ROOT,
  "pseudobulk_build_summary.tsv"
)

META_FILES <- c(

  GSE282122 = file.path(
    INPUT_ROOT,
    "GSE282122/GSE282122_candidate_marker_pseudobulk_metadata.parquet"
  ),

  SCP1884 = file.path(
    INPUT_ROOT,
    "SCP1884/SCP1884_candidate_marker_pseudobulk_metadata.parquet"
  ),

  SCP259 = file.path(
    INPUT_ROOT,
    "SCP259/SCP259_candidate_marker_pseudobulk_metadata.parquet"
  )
)


## ============================================================================
## 1. Package check
## ============================================================================

if (!requireNamespace(
  "arrow",
  quietly = TRUE
)) {

  stop(
    "Required R package 'arrow' is not installed.",
    call. = FALSE
  )
}


## ============================================================================
## 2. Helper functions
## ============================================================================

fail <- function(...) {

  stop(
    ...,
    call. = FALSE
  )
}


is_known <- function(x) {

  x <- as.character(x)

  !is.na(x) &
    x != "" &
    x != "<NA>"
}


collapse_known <- function(x) {

  x <- as.character(x)

  x <- sort(
    unique(
      x[
        is_known(x)
      ]
    )
  )

  if (length(x) == 0L) {

    return("<none>")
  }

  paste(
    x,
    collapse = " | "
  )
}


count_known <- function(x) {

  x <- as.character(x)

  length(
    unique(
      x[
        is_known(x)
      ]
    )
  )
}


safe_quantile <- function(
    x,
    prob
) {

  x <- as.numeric(x)

  x <- x[
    is.finite(x)
  ]

  if (length(x) == 0L) {

    return(
      NA_real_
    )
  }

  as.numeric(
    stats::quantile(
      x,
      probs = prob,
      names = FALSE,
      na.rm = TRUE,
      type = 7
    )
  )
}


safe_median <- function(x) {

  x <- as.numeric(x)

  x <- x[
    is.finite(x)
  ]

  if (length(x) == 0L) {

    return(
      NA_real_
    )
  }

  stats::median(x)
}


safe_min <- function(x) {

  x <- as.numeric(x)

  x <- x[
    is.finite(x)
  ]

  if (length(x) == 0L) {

    return(
      NA_real_
    )
  }

  min(x)
}


safe_max <- function(x) {

  x <- as.numeric(x)

  x <- x[
    is.finite(x)
  ]

  if (length(x) == 0L) {

    return(
      NA_real_
    )
  }

  max(x)
}


pct <- function(
    numerator,
    denominator
) {

  if (
    length(denominator) == 0L ||
    is.na(denominator) ||
    denominator == 0
  ) {

    return(
      NA_real_
    )
  }

  100 *
    numerator /
    denominator
}


write_tsv <- function(
    x,
    path
) {

  utils::write.table(
    x,
    file = path,
    sep = "\t",
    quote = FALSE,
    row.names = FALSE,
    na = "NA"
  )
}


## ============================================================================
## 3. Coarse-identity analysis roles
##
## IMPORTANT:
##
## role does NOT determine whether marker genes are calculated.
##
## All three categories remain in the marker audit.
##
## BASELINE_CANDIDATE
##   Current 20-class candidate reference taxonomy.
##
## EXTENDED_CANDIDATE
##   Biologically meaningful identities not yet accepted into the baseline
##   taxonomy.
##
## AUDIT_ONLY
##   Ambiguous/problem populations retained to expose contaminating programs.
## ============================================================================

BASELINE_CANDIDATE <- c(

  "B",
  "Plasma",

  "CD4_T",
  "CD8_T",
  "NK",
  "ILC",

  "Monocyte_Macrophage",
  "DC",
  "Mast",

  "Fibroblast",
  "Pericyte",
  "Endothelial",

  "Ileal_absorptive",
  "Colonic_absorptive",
  "Goblet",
  "Stem_TA_progenitor",
  "Paneth",
  "Enteroendocrine",

  "Glial",
  "Tuft"
)


EXTENDED_CANDIDATE <- c(

  "Unconventional_T",
  "M_like",
  "Neutrophil"
)


AUDIT_ONLY <- c(

  "Stromal_ambiguous",
  "T_ambiguous",
  "Epithelial_ambiguous",
  "Immune_ambiguous",
  "HBB_HBA_ambiguous"
)


role_map <- data.frame(

  coarse_identity = c(
    BASELINE_CANDIDATE,
    EXTENDED_CANDIDATE,
    AUDIT_ONLY
  ),

  role = c(

    rep(
      "BASELINE_CANDIDATE",
      length(
        BASELINE_CANDIDATE
      )
    ),

    rep(
      "EXTENDED_CANDIDATE",
      length(
        EXTENDED_CANDIDATE
      )
    ),

    rep(
      "AUDIT_ONLY",
      length(
        AUDIT_ONLY
      )
    )
  ),

  stringsAsFactors = FALSE
)


if (anyDuplicated(
  role_map$coarse_identity
)) {

  fail(
    "Internal error: duplicated coarse identity in role_map."
  )
}


## ============================================================================
## 4. Input/output preflight
## ============================================================================

required_inputs <- c(
  SUMMARY_FILE,
  unname(
    META_FILES
  )
)


missing_inputs <- required_inputs[
  !file.exists(
    required_inputs
  )
]


if (length(
  missing_inputs
) > 0L) {

  fail(
    "Missing required input files:\n",
    paste(
      missing_inputs,
      collapse = "\n"
    )
  )
}


dir.create(
  OUTDIR,
  recursive = TRUE,
  showWarnings = FALSE
)


output_files <- c(

  file.path(
    OUTDIR,
    "00_coarse_identity_role.tsv"
  ),

  file.path(
    OUTDIR,
    "01_pseudobulk_support_profile.tsv"
  ),

  file.path(
    OUTDIR,
    "01_pseudobulk_support_profile.parquet"
  ),

  file.path(
    OUTDIR,
    "02_identity_distribution.tsv"
  ),

  file.path(
    OUTDIR,
    "03_identity_threshold_sensitivity.tsv"
  ),

  file.path(
    OUTDIR,
    "04_global_identity_threshold_sensitivity.tsv"
  ),

  file.path(
    OUTDIR,
    "05_site_threshold_support.tsv"
  ),

  file.path(
    OUTDIR,
    "06_disease_threshold_support.tsv"
  ),

  file.path(
    OUTDIR,
    "07_inflammation_threshold_support.tsv"
  ),

  file.path(
    OUTDIR,
    "08_support_audit_summary.txt"
  ),

  file.path(
    OUTDIR,
    "09_sessionInfo.txt"
  )
)


existing_outputs <- output_files[
  file.exists(
    output_files
  )
]


if (length(
  existing_outputs
) > 0L) {

  if (!OVERWRITE) {

    fail(
      "Existing support-audit outputs detected.\n",
      "Set IBD_SUPPORT_AUDIT_OVERWRITE=1 only for an intentional rerun.\n\n",
      paste(
        existing_outputs,
        collapse = "\n"
      )
    )
  }

  unlink(
    existing_outputs
  )
}


cat("\n")
cat("====================================================================\n")
cat("IBD SIGNATURE V2: MARKER PSEUDOBULK SUPPORT AUDIT\n")
cat("====================================================================\n")
cat("No expression matrix will be loaded.\n")
cat("No pseudobulk will be filtered.\n")
cat(
  "Sensitivity thresholds: ",
  paste(
    SUPPORT_THRESHOLDS,
    collapse = ", "
  ),
  " cells\n",
  sep = ""
)


## ============================================================================
## 5. Read Stage-08 build summary
## ============================================================================

build_summary <- utils::read.delim(

  SUMMARY_FILE,

  header = TRUE,

  stringsAsFactors = FALSE,

  check.names = FALSE
)


required_summary_cols <- c(

  "dataset",

  "n_pseudobulks",

  "n_candidate_cells"
)


missing_summary_cols <- setdiff(

  required_summary_cols,

  colnames(
    build_summary
  )
)


if (length(
  missing_summary_cols
) > 0L) {

  fail(
    "pseudobulk_build_summary.tsv is missing columns: ",
    paste(
      missing_summary_cols,
      collapse = ", "
    )
  )
}


## ============================================================================
## 6. Load pseudobulk metadata
##
## IMPORTANT:
##
## Read the DATASET-SPECIFIC metadata written by save_dataset(), because these
## contain raw_library_size.
##
## The combined Stage-08 metadata was created before raw_library_size was
## attached and therefore is intentionally not used here.
## ============================================================================

cat(
  "\n[1] Loading per-dataset pseudobulk metadata...\n"
)


required_meta_cols <- c(

  "pb_id",

  "dataset",

  "donor_id",

  "sample_id",

  "site",

  "disease",

  "inflammation",

  "coarse_identity",

  "n_cells",

  "raw_library_size"
)


meta_list <- vector(

  mode = "list",

  length = length(
    META_FILES
  )
)


names(
  meta_list
) <- names(
  META_FILES
)


for (dataset in names(
  META_FILES
)) {

  x <- as.data.frame(
    arrow::read_parquet(
      META_FILES[[dataset]]
    )
  )


  missing_cols <- setdiff(

    required_meta_cols,

    colnames(x)
  )


  if (length(
    missing_cols
  ) > 0L) {

    fail(
      dataset,
      " metadata is missing columns: ",
      paste(
        missing_cols,
        collapse = ", "
      )
    )
  }


  if (anyDuplicated(
    x$pb_id
  )) {

    fail(
      dataset,
      " metadata contains duplicated pb_id values."
    )
  }


  if (!all(
    x$dataset ==
      dataset
  )) {

    fail(
      dataset,
      " metadata contains inconsistent dataset labels."
    )
  }


  summary_row <- build_summary[
    build_summary$dataset ==
      dataset,
    ,
    drop = FALSE
  ]


  if (nrow(
    summary_row
  ) != 1L) {

    fail(
      "Expected exactly one build-summary row for ",
      dataset,
      "."
    )
  }


  expected_pb <- as.integer(
    summary_row$n_pseudobulks[[1L]]
  )


  expected_cells <- as.integer(
    summary_row$n_candidate_cells[[1L]]
  )


  if (nrow(x) != expected_pb) {

    fail(
      dataset,
      " pseudobulk-count mismatch: metadata=",
      nrow(x),
      ", build-summary=",
      expected_pb
    )
  }


  if (sum(
    x$n_cells
  ) != expected_cells) {

    fail(
      dataset,
      " candidate-cell closure failed: metadata=",
      sum(
        x$n_cells
      ),
      ", build-summary=",
      expected_cells
    )
  }


  if (
    any(
      !is.finite(
        x$n_cells
      )
    ) ||
    any(
      x$n_cells <
        1
    )
  ) {

    fail(
      dataset,
      " contains invalid n_cells values."
    )
  }


  if (
    any(
      !is.finite(
        x$raw_library_size
      )
    ) ||
    any(
      x$raw_library_size <=
        0
    )
  ) {

    fail(
      dataset,
      " contains invalid raw_library_size values."
    )
  }


  meta_list[[dataset]] <- x


  cat(
    "  ",
    dataset,
    ": ",
    format(
      nrow(x),
      big.mark = ","
    ),
    " pseudobulks; ",
    format(
      sum(
        x$n_cells
      ),
      big.mark = ","
    ),
    " cells\n",
    sep = ""
  )
}


all_meta <- do.call(
  rbind,
  meta_list
)


rownames(
  all_meta
) <- NULL


if (anyDuplicated(
  all_meta$pb_id
)) {

  fail(
    "Global pseudobulk IDs are not unique."
  )
}


if (
  nrow(
    all_meta
  ) !=
    sum(
      build_summary$n_pseudobulks
    )
) {

  fail(
    "Global pseudobulk count does not match Stage-08 build summary."
  )
}


if (
  sum(
    all_meta$n_cells
  ) !=
    sum(
      build_summary$n_candidate_cells
    )
) {

  fail(
    "Global candidate-cell count does not match Stage-08 build summary."
  )
}


cat(
  "  TOTAL: ",
  format(
    nrow(
      all_meta
    ),
    big.mark = ","
  ),
  " pseudobulks; ",
  format(
    sum(
      all_meta$n_cells
    ),
    big.mark = ","
  ),
  " cells\n",
  sep = ""
)


## ============================================================================
## 7. Assign coarse-group roles
## ============================================================================

cat(
  "\n[2] Assigning coarse-group analysis roles...\n"
)


observed_identities <- sort(
  unique(
    all_meta$coarse_identity
  )
)


unknown_identities <- setdiff(

  observed_identities,

  role_map$coarse_identity
)


if (length(
  unknown_identities
) > 0L) {

  fail(
    "Observed coarse identities missing from role_map: ",
    paste(
      unknown_identities,
      collapse = ", "
    )
  )
}


observed_role_map <- role_map[
  role_map$coarse_identity %in%
    observed_identities,
  ,
  drop = FALSE
]


observed_role_map <- observed_role_map[
  order(
    observed_role_map$role,
    observed_role_map$coarse_identity
  ),
  ,
  drop = FALSE
]


all_meta$role <- role_map$role[
  match(
    all_meta$coarse_identity,
    role_map$coarse_identity
  )
]


if (anyNA(
  all_meta$role
)) {

  fail(
    "Role assignment produced NA values."
  )
}


for (threshold in SUPPORT_THRESHOLDS) {

  flag_name <- paste0(
    "support_ge_",
    threshold,
    "_cells"
  )

  all_meta[[flag_name]] <- (
    all_meta$n_cells >=
      threshold
  )
}


write_tsv(

  observed_role_map,

  file.path(
    OUTDIR,
    "00_coarse_identity_role.tsv"
  )
)


write_tsv(

  all_meta,

  file.path(
    OUTDIR,
    "01_pseudobulk_support_profile.tsv"
  )
)


arrow::write_parquet(

  all_meta,

  file.path(
    OUTDIR,
    "01_pseudobulk_support_profile.parquet"
  )
)


cat(
  "  Observed coarse groups: ",
  length(
    observed_identities
  ),
  "\n",
  sep = ""
)


print(
  table(
    all_meta$role
  )
)


## ============================================================================
## 8. Unfiltered distribution audit
## ============================================================================

cat(
  "\n[3] Building identity-level distribution table...\n"
)


keys <- unique(
  all_meta[
    c(
      "dataset",
      "coarse_identity",
      "role"
    )
  ]
)


keys <- keys[
  order(
    keys$dataset,
    keys$role,
    keys$coarse_identity
  ),
  ,
  drop = FALSE
]


distribution_rows <- vector(
  "list",
  nrow(
    keys
  )
)


for (i in seq_len(
  nrow(
    keys
  )
)) {

  dataset <- keys$dataset[i]

  identity <- keys$coarse_identity[i]

  role <- keys$role[i]


  sub <- all_meta[
    all_meta$dataset ==
      dataset &
      all_meta$coarse_identity ==
        identity,
    ,
    drop = FALSE
  ]


  cells <- sub$n_cells

  libs <- sub$raw_library_size


  distribution_rows[[i]] <- data.frame(

    dataset = dataset,

    coarse_identity = identity,

    role = role,

    n_pseudobulks =
      nrow(sub),

    n_samples =
      length(
        unique(
          sub$sample_id
        )
      ),

    n_donors =
      length(
        unique(
          sub$donor_id
        )
      ),

    total_cells =
      sum(cells),

    cells_min =
      safe_min(cells),

    cells_q05 =
      safe_quantile(
        cells,
        0.05
      ),

    cells_q10 =
      safe_quantile(
        cells,
        0.10
      ),

    cells_q25 =
      safe_quantile(
        cells,
        0.25
      ),

    cells_median =
      safe_median(cells),

    cells_q75 =
      safe_quantile(
        cells,
        0.75
      ),

    cells_q90 =
      safe_quantile(
        cells,
        0.90
      ),

    cells_q95 =
      safe_quantile(
        cells,
        0.95
      ),

    cells_q99 =
      safe_quantile(
        cells,
        0.99
      ),

    cells_max =
      safe_max(cells),

    library_min =
      safe_min(libs),

    library_q05 =
      safe_quantile(
        libs,
        0.05
      ),

    library_q10 =
      safe_quantile(
        libs,
        0.10
      ),

    library_q25 =
      safe_quantile(
        libs,
        0.25
      ),

    library_median =
      safe_median(libs),

    library_q75 =
      safe_quantile(
        libs,
        0.75
      ),

    library_q90 =
      safe_quantile(
        libs,
        0.90
      ),

    library_q95 =
      safe_quantile(
        libs,
        0.95
      ),

    library_q99 =
      safe_quantile(
        libs,
        0.99
      ),

    library_max =
      safe_max(libs),

    n_sites =
      count_known(
        sub$site
      ),

    sites =
      collapse_known(
        sub$site
      ),

    n_diseases =
      count_known(
        sub$disease
      ),

    diseases =
      collapse_known(
        sub$disease
      ),

    n_inflammation_states =
      count_known(
        sub$inflammation
      ),

    inflammation_states =
      collapse_known(
        sub$inflammation
      ),

    stringsAsFactors = FALSE
  )
}


distribution_table <- do.call(
  rbind,
  distribution_rows
)


rownames(
  distribution_table
) <- NULL


write_tsv(

  distribution_table,

  file.path(
    OUTDIR,
    "02_identity_distribution.tsv"
  )
)


## ============================================================================
## 9. Dataset-specific threshold sensitivity
## ============================================================================

cat(
  "\n[4] Building threshold-sensitivity table...\n"
)


threshold_rows <- list()

row_id <- 0L


for (i in seq_len(
  nrow(
    keys
  )
)) {

  dataset <- keys$dataset[i]

  identity <- keys$coarse_identity[i]

  role <- keys$role[i]


  sub_all <- all_meta[
    all_meta$dataset ==
      dataset &
      all_meta$coarse_identity ==
        identity,
    ,
    drop = FALSE
  ]


  total_pb <- nrow(
    sub_all
  )


  total_samples <- length(
    unique(
      sub_all$sample_id
    )
  )


  total_donors <- length(
    unique(
      sub_all$donor_id
    )
  )


  total_cells <- sum(
    sub_all$n_cells
  )


  for (threshold in SUPPORT_THRESHOLDS) {

    sub <- sub_all[
      sub_all$n_cells >=
        threshold,
      ,
      drop = FALSE
    ]


    n_supported_pb <- nrow(
      sub
    )


    n_supported_samples <- length(
      unique(
        sub$sample_id
      )
    )


    n_supported_donors <- length(
      unique(
        sub$donor_id
      )
    )


    supported_cells <- sum(
      sub$n_cells
    )


    donor_counts <- integer(
      0
    )


    if (nrow(
      sub
    ) > 0L) {

      donor_counts <- as.integer(
        table(
          sub$donor_id
        )
      )
    }


    row_id <- row_id +
      1L


    threshold_rows[[row_id]] <- data.frame(

      dataset = dataset,

      coarse_identity = identity,

      role = role,

      min_cells_per_pseudobulk =
        threshold,

      n_total_pseudobulks =
        total_pb,

      n_supported_pseudobulks =
        n_supported_pb,

      pct_pseudobulks_retained =
        pct(
          n_supported_pb,
          total_pb
        ),

      n_total_samples =
        total_samples,

      n_supported_samples =
        n_supported_samples,

      pct_samples_retained =
        pct(
          n_supported_samples,
          total_samples
        ),

      n_total_donors =
        total_donors,

      n_supported_donors =
        n_supported_donors,

      pct_donors_retained =
        pct(
          n_supported_donors,
          total_donors
        ),

      total_cells =
        total_cells,

      supported_cells =
        supported_cells,

      pct_cells_retained =
        pct(
          supported_cells,
          total_cells
        ),

      supported_cells_min =
        safe_min(
          sub$n_cells
        ),

      supported_cells_q25 =
        safe_quantile(
          sub$n_cells,
          0.25
        ),

      supported_cells_median =
        safe_median(
          sub$n_cells
        ),

      supported_cells_q75 =
        safe_quantile(
          sub$n_cells,
          0.75
        ),

      supported_cells_max =
        safe_max(
          sub$n_cells
        ),

      supported_library_min =
        safe_min(
          sub$raw_library_size
        ),

      supported_library_q25 =
        safe_quantile(
          sub$raw_library_size,
          0.25
        ),

      supported_library_median =
        safe_median(
          sub$raw_library_size
        ),

      supported_library_q75 =
        safe_quantile(
          sub$raw_library_size,
          0.75
        ),

      supported_library_max =
        safe_max(
          sub$raw_library_size
        ),

      median_supported_samples_per_donor =
        safe_median(
          donor_counts
        ),

      max_supported_samples_per_donor =
        safe_max(
          donor_counts
        ),

      n_sites_supported =
        count_known(
          sub$site
        ),

      sites_supported =
        collapse_known(
          sub$site
        ),

      n_unknown_site_pseudobulks =
        sum(
          !is_known(
            sub$site
          )
        ),

      n_diseases_supported =
        count_known(
