## ============================================================================
## 11. Stratified support helper
## ============================================================================

build_stratified_support <- function(
    meta,
    field,
    field_label,
    thresholds
) {

  rows <- list()

  row_id <- 0L


  for (dataset in sort(
    unique(
      meta$dataset
    )
  )) {

    dataset_meta <- meta[
      meta$dataset ==
        dataset,
      ,
      drop = FALSE
    ]


    for (identity in sort(
      unique(
        dataset_meta$coarse_identity
      )
    )) {

      identity_meta <- dataset_meta[
        dataset_meta$coarse_identity ==
          identity,
        ,
        drop = FALSE
      ]


      role <- unique(
        identity_meta$role
      )


      if (length(
        role
      ) != 1L) {

        fail(
          "Role is not unique for ",
          dataset,
          " / ",
          identity,
          "."
        )
      }


      for (threshold in thresholds) {

        supported <- identity_meta[
          identity_meta$n_cells >=
            threshold,
          ,
          drop = FALSE
        ]


        if (nrow(
          supported
        ) == 0L) {

          next
        }


        values <- as.character(
          supported[[field]]
        )


        strata <- sort(
          unique(
            values[
              is_known(
                values
              )
            ]
          )
        )


        if (length(
          strata
        ) == 0L) {

          next
        }


        for (stratum in strata) {

          sub <- supported[
            values ==
              stratum,
            ,
            drop = FALSE
          ]


          row_id <- row_id +
            1L


          rows[[row_id]] <- data.frame(

            dataset =
              dataset,

            coarse_identity =
              identity,

            role =
              role,

            min_cells_per_pseudobulk =
              threshold,

            stratum =
              stratum,

            n_supported_pseudobulks =
              nrow(
                sub
              ),

            n_supported_samples =
              length(
                unique(
                  sub$sample_id
                )
              ),

            n_supported_donors =
              length(
                unique(
                  sub$donor_id
                )
              ),

            supported_cells =
              sum(
                sub$n_cells
              ),

            median_cells_per_pseudobulk =
              safe_median(
                sub$n_cells
              ),

            median_library_size =
              safe_median(
                sub$raw_library_size
              ),

            stringsAsFactors = FALSE
          )
        }
      }
    }
  }


  if (length(
    rows
  ) == 0L) {

    out <- data.frame(

      dataset = character(0),

      coarse_identity = character(0),

      role = character(0),

      min_cells_per_pseudobulk = integer(0),

      stratum = character(0),

      n_supported_pseudobulks = integer(0),

      n_supported_samples = integer(0),

      n_supported_donors = integer(0),

      supported_cells = numeric(0),

      median_cells_per_pseudobulk = numeric(0),

      median_library_size = numeric(0),

      stringsAsFactors = FALSE
    )

  } else {

    out <- do.call(
      rbind,
      rows
    )

    rownames(
      out
    ) <- NULL
  }


  colnames(out)[
    colnames(out) ==
      "stratum"
  ] <- field_label


  out
}


